                while j < high and prefix[j] - prefix[i] < lower:
                    j += 1
                while k < high and prefix[k] - prefix[i] <= upper:
                    k += 1
                count += k - j
            prefix[low:high] = sorted(prefix[low:high])
            return count

        return merge_sort(0, len(prefix))
