class Solution {
    public int countRangeSum(int[] nums, int lower, int upper) {
        int n = nums.length;
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + nums[i];
        return mergeSort(prefix, 0, n + 1, lower, upper);
    }
    private int mergeSort(long[] prefix, int low, int high, int lower, int upper) {
        if (high - low <= 1) return 0;
        int mid = (low + high) / 2;
        int count = mergeSort(prefix, low, mid, lower, upper) + mergeSort(prefix, mid, high, lower, upper);
        int j = mid, k = mid;
        for (int i = low; i < mid; i++) {
            while (j < high && prefix[j] - prefix[i] < lower) j++;
            while (k < high && prefix[k] - prefix[i] <= upper) k++;
            count += k - j;
        }
        Arrays.sort(prefix, low, high);
        return count;
    }
}

/**
 * @param {number[]} nums
 * @param {number} lower
 * @param {number} upper
 * @return {number}
