var countRangeSum = function(nums, lower, upper) {
    const n = nums.length;
    const prefix = [0];
    for (const x of nums) prefix.push(prefix[prefix.length - 1] + x);
    const mergeSort = (low, high) => {
        if (high - low <= 1) return 0;
        const mid = Math.floor((low + high) / 2);
        let count = mergeSort(low, mid) + mergeSort(mid, high);
        let j = mid, k = mid;
        for (let i = low; i < mid; i++) {
            while (j < high && prefix[j] - prefix[i] < lower) j++;
            while (k < high && prefix[k] - prefix[i] <= upper) k++;
            count += k - j;
        }
        const sorted = prefix.slice(low, high).sort((a, b) => a - b);
        for (let i = 0; i < sorted.length; i++) prefix[low + i] = sorted[i];
        return count;
    };
    return mergeSort(0, prefix.length);
};
